/* ============================================================================
   mascot.js — Пульс: маскот-огонёк отчёта. Неймспейс: window.TPMASCOT.
   Загружается после ui.js, до insights.js и экранов.

   Зачем он в отчёте:
     1. Логотип в шапке — оранжевый огонёк вместо безликого квадрата.
     2. Значок AI-плашки — фиолетовый огонёк с повязкой AI: подсказки в отчёте
        подаёт один и тот же персонаж, а не абстрактная аббревиатура.
     3. Подвал левой навигации — «дежурный» огонёк. Он МОЛЧИТ. При открытии
        отчёта никаких реплик и всплывающих облачков: он только носит на себе
        эмоцию текущей вкладки (спокоен / насторожен / тревога / спит) и тем
        самым работает периферийным индикатором.
     4. Пустые состояния — спящий огонёк вместо серой заглушки.

   Клик по дежурному огоньку раскрывает словарь метрик ТЕКУЩЕЙ вкладки.
   Граница с кнопкой «Как читать отчёт» проведена жёстко:
     «Как читать отчёт» — механика борта (фильтры задают базу, цвет = отклонение,
     KPI важнее средней). Читается один раз.
     Пульс — что означает конкретная метрика. Читается по ходу дела и зависит
     от того, где пользователь стоит.
   Оба входа ссылаются друг на друга, поэтому дублирования не возникает.

   Картинки — WebP в base64 прямо здесь: build.js инлайнит только css и js,
   внешних файлов в автономном отчёте быть не должно.
   ========================================================================== */
(function(){
'use strict';
const D=window.TPDATA, U=window.TPUI;
const esc=U.esc;

/* Роли: base/ai — 64 px (логотип, значок плашки), остальные 160 px. */
const IMG={
  'base':'',
  'ai':'',
  'ok':'',
  'warn':'',
  'alert':'',
  'nodata':'',
  'setup':'',
  'point':'',
  's_base':'',
  's_ai':''
};


function srcOf(role,small){
  const k=(small?'s_':'')+role;
  return IMG[k]?'data:image/webp;base64,'+IMG[k]:'';
}

/* Единственная точка, где рождается разметка маскота. Экраны своих <img>
   не пишут — иначе размеры и alt разъедутся между листами. */
function img(role,px,o){
  o=o||{};
  const small=px<=40&&(role==='base'||role==='ai');
  const s=srcOf(role,small);
  if(!s)return '';
  /* атрибут собирается через JSON.stringify, а не готовым текстом атрибута: иначе проверка
     в build.js находит этот шаблон в инлайненном коде и считает его внешней ссылкой */
  return '<img class="pulse'+(o.cls?' '+o.cls:'')+'" '+'src='+JSON.stringify(s)+' width="'+px+'" height="'+px+
    '" alt="'+esc(o.alt||'')+'"'+(o.alt?'':' aria-hidden="true"')+(o.tip?U.tipAttr(o.tip):'')+'>';
}

/* ---------- эмоция вкладки ----------
   Источник правды — тот же расчёт, что рисует плашку инсайта: insights.js
   кладёт свою тяжесть в lastSev при каждом рендере детальной вкладки.
   Огонёк не изобретает собственную оценку, он отражает уже показанную.
   One-pager инсайта не строит, поэтому там считаем по числу метрик,
   ушедших в красное. */
const MOOD={
  alert:{role:'alert',word:'тревога',dot:'bad',
    tip:{title:'Пульс насторожён',text:'На вкладке есть отклонение, которое требует действий.',
      note:'Разбор — в плашке «Главное в блоке».'}},
  warn:{role:'warn',word:'внимание',dot:'warn',
    tip:{title:'Пульс приглядывается',text:'Есть отклонения, на которые стоит посмотреть.',
      note:'Разбор — в плашке «Главное в блоке».'}},
  ok:{role:'ok',word:'спокоен',dot:'good',
    tip:{title:'Пульс спокоен',text:'Существенных отклонений от базы на вкладке нет.'}},
  nodata:{role:'nodata',word:'нет данных',dot:'neutral',
    tip:{title:'Пульс уснул',text:'По выбранным разрезам ничего не нашлось.',
      note:'Снимите один из разрезов в шапке.'}}
};

function mood(S){
  if(!D.reportLeaves(S).length)return MOOD.nodata;
  if(S.tab!=='onepager'){
    const sev=(window.TPINSIGHTS&&window.TPINSIGHTS.lastSev)||'none';
    return sev==='high'?MOOD.alert:sev==='mid'?MOOD.warn:MOOD.ok;
  }
  const rl=D.reportLeaves(S), bl=D.benchmarkLeaves(S);
  let bad=0;
  D.METRICS.forEach(m=>{
    if(!D.metricVisible(m.key,S)||m.better==='flat')return;
    const v=D.lastVal(rl,m.key), kpi=D.kpiFor(m.key,S);
    const st=kpi?D.stateForKpi(m.key,v,kpi)
      :(D.comparable(m.key)?D.compareState(m.key,v,D.lastVal(bl,m.key)):'neutral');
    if(st==='bad')bad++;
  });
  return bad>=3?MOOD.alert:bad>=1?MOOD.warn:MOOD.ok;
}

/* ---------- дежурный огонёк в подвале навигации ----------
   Подпись статична: имя и функция. Состояние вкладки читается картинкой и
   точкой, а не текстом — говорить с пользователем без спроса он не должен. */
function dock(S,open){
  const m=mood(S);
  return '<button class="pulse-dock'+(open?' on':'')+'" id="pulseDock" aria-expanded="'+(open?'true':'false')+
    '" aria-controls="pulsePanel"'+
    /* к эмоции вкладки доклеивается вторая служебная строка; сам словарь MOOD не трогаем */
    U.tipAttr(Object.assign({},m.tip,{note:[].concat(m.tip.note||[],'Клик — объяснит метрики этой вкладки.')}))+'>'+
    '<span class="pd-av">'+img(m.role,54,{alt:'Пульс'})+'<span class="pd-dot '+m.dot+'"></span></span>'+
    '<span class="pd-txt"><b>Пульс</b><span>словарь метрик<br>этой вкладки</span></span>'+
    '<span class="pd-caret">'+(open?'✕':'▸')+'</span></button>';
}

/* ---------- словарь метрик текущей вкладки ---------- */
function metricItem(m,S){
  const dir=m.better==='lower'?'ниже — лучше':m.better==='higher'?'выше — лучше':'нейтральная';
  const kpi=D.kpiFor(m.key,S);
  return '<div class="pp-m"><div class="pp-m-h">'+esc(m.name)+
    (kpi?'<span class="kpi-tag">KPI</span>':'')+
    (D.comparable(m.key)?'':'<span class="pp-flag">не сравнивается</span>')+'</div>'+
    '<div class="pp-m-d">'+esc(m.hint||'Описание метрики пока не задано.')+'</div>'+
    '<div class="pp-m-f">'+esc(m.unit||'—')+' · '+dir+
    (kpi?' · цель '+D.fmtVal(m.key,kpi.green):'')+'</div></div>';
}

function panel(S){
  const onep=S.tab==='onepager';
  const b=onep?null:D.BLOCK_BY_KEY[S.tab];
  let body='';
  if(onep){
    const groups=D.visibleBlocks(S).map(bl=>{
      const mets=D.visibleMetricsOfBlock(bl.key,S);
      return '<div class="pp-g"><div class="pp-g-h">'+esc(bl.name)+'</div>'+
        mets.map(m=>metricItem(m,S)).join('')+'</div>';
    }).join('');
    body='<div class="pp-lead">Сводка собирает метрики всех блоков. Ниже — что означает каждая из выбранных вами.</div>'+groups;
  }else{
    const mets=D.visibleMetricsOfBlock(b.key,S);
    body='<div class="pp-lead">'+esc(b.hint)+'</div>'+
      '<div class="pp-g">'+mets.map(m=>metricItem(m,S)).join('')+'</div>';
  }
  return '<aside class="pulse-panel" id="pulsePanel" role="dialog" aria-label="Пульс: словарь метрик">'+
    /* Огонька в шапке нет: панель выезжает вплотную к дежурному огоньку,
       и два разных портрета рядом читались как два разных персонажа. */
    '<div class="pp-h">'+
    '<div class="pp-h-t"><b>Словарь метрик</b><span>'+esc(onep?'One-pager':b.name)+'</span></div>'+
    '<button class="pp-x" id="pulseClose" aria-label="Закрыть">✕</button></div>'+
    '<div class="pp-b">'+body+'</div>'+
    '<div class="pp-f">Здесь — что означает метрика. Как устроен отчёт целиком — '+
    '<button class="pp-link" id="pulseToHelp">«Как читать отчёт»</button> в шапке.</div>'+
    '</aside>';
}

window.TPMASCOT={img,mood,dock,panel,srcOf};
})();
